#!/usr/bin/env python3
import os

def get_parent_env():
    try:
        ppid = os.getppid()
        with open(f"/proc/{ppid}/environ", "rb") as f:
            data = f.read()
        env = {}
        for entry in data.split(b'\x00'):
            if not entry:
                continue
            if b'=' in entry:
                k, _, v = entry.partition(b'=')
                try:
                    env[k.decode('utf-8', 'replace')] = v.decode('utf-8', 'replace')
                except Exception:
                    pass
        return env
    except Exception:
        return {}

def main():
    env = get_parent_env()
    print(bool("AGENT_API_KEY" in env))

if __name__ == "__main__":
    main()

